"""
ゲーム探索 (Game Search) & Grundy数 (Nim)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
- alphabeta(state, depth, alpha, beta, is_max, get_moves, eval_fn):
  Alpha-Beta枝刈りによる2人零和完全情報ゲームの探索
- grundy(state, get_transitions, memo):
  不偏ゲームのGrundy数 (Nim値) をメモ化再帰で計算
  - 状態遷移のGrundy数の mex (最小除外値) がその状態のGrundy数
  - 複数ゲームの並行進行は Grundy数の XOR 和 (Nim-sum) で勝敗判定 (XOR和 > 0 で先手必勝)
"""

# https://github.com/ddfkit/acsampl/blob/main/game.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def alphabeta(s,d,al,be,mx,mv_fn,ev_fn):
    mvs=mv_fn(s)
    if not d or not mvs:return ev_fn(s)
    if mx:
        v=-float('inf')
        for nxt in mvs:
            v=max(v,alphabeta(nxt,d-1,al,be,False,mv_fn,ev_fn));al=max(al,v)
            if be<=al:break
        return v
    else:
        v=float('inf')
        for nxt in mvs:
            v=min(v,alphabeta(nxt,d-1,al,be,True,mv_fn,ev_fn));be=min(be,v)
            if be<=al:break
        return v

# https://github.com/ddfkit/acsampl/blob/main/game.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def mex(s):
    m=0
    while m in s:m+=1
    return m

# https://github.com/ddfkit/acsampl/blob/main/game.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def calc_grundy(s,nxt_fn,memo=None):
    if memo is None:memo={}
    if s in memo:return memo[s]
    g=mex({calc_grundy(nxt,nxt_fn,memo) for nxt in nxt_fn(s)})
    memo[s]=g;return g

if __name__ == "__main__":
    def nim_moves(n):
        return [n - i for i in (1, 2, 3) if n - i >= 0]
    memo = {}
    for i in range(12):
        assert (calc_grundy(i, nim_moves, memo) == (i % 4))
    print("game.py: tests passed!")
